import RNA
import random
from multiprocessing import Pool

target = "(..((....((..((....((..((....(..((..((....((..((..((....(..((..((..((....((..((..((..((....((..((..((..((..((....((..((..((..((..((....((..((..((..((..((..((....((..((..((..((..((..((....((..((..((..((..((..((......))..))..))..))..))..))))..))..))..))..))..))))..))..))..))..))..))))..))..))..))..))))..))..))..))..))))..))..))..))))..))..))..)))..))..))))..))..)))..))))..))))..)"

stack=[]
pairs={}
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i
        pairs[i]=j

def init_seq(seed):
    rng = random.Random(seed)
    seq = ['A']*len(target)
    # 5'-side unpaired stays A; for pairs, randomize GC/CG/AU
    for i in range(len(target)):
        if i in pairs and i < pairs[i]:
            r = rng.random()
            if r < 0.4:
                seq[i]='G'; seq[pairs[i]]='C'
            elif r < 0.8:
                seq[i]='C'; seq[pairs[i]]='G'
            else:
                seq[i]='A'; seq[pairs[i]]='U'
    # also randomize unpaired linkers a bit: keep A mostly but some U
    return ''.join(seq)

def worker(seed):
    s0 = init_seq(seed)
    try:
        s_inv, cost = RNA.inverse_fold(s0, target)
    except Exception as e:
        return (999, '', seed)
    fc = RNA.fold_compound(s_inv)
    ss, mfe = fc.mfe()
    sc = RNA.bp_distance(ss, target)
    return (sc, s_inv, seed)

if __name__ == '__main__':
    import sys
    n = int(sys.argv[1]) if len(sys.argv)>1 else 16
    with Pool(n) as p:
        results = p.map(worker, range(n))
    results.sort()
    sc, seq, seed = results[0]
    print("BEST_SCORE", sc, "seed", seed, flush=True)
    print("BEST_SEQ", seq, flush=True)
    print("LEN", len(seq), flush=True)
    # show top 5
    for r in results[:5]:
        print("  score", r[0], "seed", r[2], flush=True)
